namespace Fulfil.Domain;

public abstract class Record { public Guid Id { get; set; } = Guid.NewGuid(); public Guid MerchantId { get; set; } }
public class Merchant { public Guid Id { get; set; } = Guid.NewGuid(); public string Name { get; set; } = ""; public string Slug { get; set; } = ""; }
public class Account : Record { public string Email { get; set; } = ""; public string Name { get; set; } = ""; public string PasswordHash { get; set; } = ""; public string Role { get; set; } = "customer"; public Guid? WarehouseId { get; set; } public bool Guest { get; set; } }
public class Product : Record { public string Sku { get; set; } = ""; public string Name { get; set; } = ""; public string Variant { get; set; } = ""; public string Category { get; set; } = ""; public string Description { get; set; } = ""; public string Color { get; set; } = "#c8d5df"; public long Price { get; set; } public bool Active { get; set; } = true; }
public class Warehouse : Record { public string Name { get; set; } = ""; public string Code { get; set; } = ""; public string City { get; set; } = ""; public bool Active { get; set; } = true; public int Priority { get; set; } public long ShippingCost { get; set; } = 500; }
public class Inventory : Record { public Guid ProductId { get; set; } public Guid WarehouseId { get; set; } public int OnHand { get; set; } public int Reserved { get; set; } public int Held { get; set; } public int Version { get; set; } public int ReorderPoint { get; set; } = 10; public int ReorderTarget { get; set; } = 50; public int Available => OnHand - Reserved - Held; }
public class Adjustment : Record { public Guid ProductId { get; set; } public Guid WarehouseId { get; set; } public int Quantity { get; set; } public string Reason { get; set; } = ""; public string Reference { get; set; } = ""; public Guid? ActorId { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Reservation : Record { public Guid OrderId { get; set; } public Guid ProductId { get; set; } public Guid WarehouseId { get; set; } public int Quantity { get; set; } public int Fulfilled { get; set; } public string State { get; set; } = "reserved"; public DateTime ExpiresAt { get; set; } = DateTime.UtcNow.AddMinutes(15); }
public class Order : Record { public string PromotionsJson { get; set; } = "[]"; public Guid CustomerId { get; set; } public string Number { get; set; } = ""; public string Email { get; set; } = ""; public string Address { get; set; } = ""; public string State { get; set; } = "reserved"; public string PaymentState { get; set; } = "pending"; public string FulfillmentState { get; set; } = "unfulfilled"; public string LinesJson { get; set; } = "[]"; public string TaxJson { get; set; } = "[]"; public string Currency { get; set; } = "USD"; public long Subtotal { get; set; } public long Discount { get; set; } public long Shipping { get; set; } public long Tax { get; set; } public long Total { get; set; } public long Captured { get; set; } public long Refunded { get; set; } public long RefundPending { get; set; } public Guid? PromotionId { get; set; } public string CheckoutKey { get; set; } = ""; public string PaymentMethod { get; set; } = ""; public string? ProviderId { get; set; } public string? ClientSecret { get; set; } public string? Error { get; set; } public int Attempts { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime UpdatedAt { get; set; } = DateTime.UtcNow; }
public record OrderLine(Guid ProductId, string Sku, string Name, string Variant, int Quantity, long UnitPrice, long Discount, long Tax);
public record QuantityLine(Guid ProductId, int Quantity);
public class OrderEvent : Record { public Guid OrderId { get; set; } public string Kind { get; set; } = ""; public string Detail { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class PaymentAttempt : Record { public Guid OrderId { get; set; } public string Operation { get; set; } = ""; public string State { get; set; } = "pending"; public string? ProviderId { get; set; } public string? Error { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Refund : Record { public Guid OrderId { get; set; } public Guid? ReturnId { get; set; } public long Amount { get; set; } public string Reason { get; set; } = ""; public string State { get; set; } = "pending"; public string? ProviderId { get; set; } public int Attempts { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Fulfillment : Record { public Guid OrderId { get; set; } public Guid WarehouseId { get; set; } public string LinesJson { get; set; } = "[]"; public string Carrier { get; set; } = ""; public string Tracking { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class ReturnRequest : Record { public Guid OrderId { get; set; } public Guid CustomerId { get; set; } public string LinesJson { get; set; } = "[]"; public string Reason { get; set; } = ""; public string State { get; set; } = "requested"; public string? Decision { get; set; } public Guid? WarehouseId { get; set; } public bool Restocked { get; set; } public Guid? ReplacementProductId { get; set; } public Guid? ExchangeOrderId { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Promotion : Record { public string Segment { get; set; } = "all"; public int Priority { get; set; } public bool Stackable { get; set; } public string ExclusionsJson { get; set; } = "[]"; public int RuleVersion { get; set; } = 1; public string Code { get; set; } = ""; public string Kind { get; set; } = "percent"; public int Value { get; set; } public long Minimum { get; set; } public int GlobalLimit { get; set; } = 1000; public int PerCustomerLimit { get; set; } = 1; public int Uses { get; set; } public Guid? ProductId { get; set; } public DateTime StartsAt { get; set; } = DateTime.UtcNow; public DateTime EndsAt { get; set; } = DateTime.UtcNow.AddMonths(3); public bool Active { get; set; } = true; }
public class PromotionUsage : Record { public Guid PromotionId { get; set; } public Guid CustomerId { get; set; } public Guid OrderId { get; set; } }
public class TaxRate : Record { public string Name { get; set; } = "Sales tax"; public int BasisPoints { get; set; } = 825; public bool Active { get; set; } = true; }
public class Transfer : Record { public Guid? OwnerId { get; set; } public string NextAction { get; set; } = ""; public Guid SourceId { get; set; } public Guid DestinationId { get; set; } public string Number { get; set; } = ""; public string State { get; set; } = "draft"; public string LinesJson { get; set; } = "[]"; public string ReceivedJson { get; set; } = "[]"; public string LostJson { get; set; } = "[]"; public string Reason { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Supplier : Record { public string Name { get; set; } = ""; public string Email { get; set; } = ""; public int LeadDays { get; set; } = 7; }
public record PurchaseLine(Guid ProductId, int Quantity, long UnitCost);
public class PurchaseOrder : Record { public string Exception { get; set; } = ""; public Guid SupplierId { get; set; } public Guid WarehouseId { get; set; } public string Number { get; set; } = ""; public string State { get; set; } = "draft"; public string LinesJson { get; set; } = "[]"; public string ReceivedJson { get; set; } = "[]"; public Guid? ApprovedBy { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class GoodsReceipt : Record { public string Disposition { get; set; } = "accepted"; public string Reason { get; set; } = ""; public Guid PurchaseOrderId { get; set; } public string LinesJson { get; set; } = "[]"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class CycleCount : Record { public Guid? AssignedTo { get; set; } public DateTime? ObservedAt { get; set; } public Guid WarehouseId { get; set; } public Guid ProductId { get; set; } public Guid CreatedBy { get; set; } public Guid? ApprovedBy { get; set; } public int Expected { get; set; } public int InventoryVersion { get; set; } public int? Counted { get; set; } public string State { get; set; } = "open"; public string Reason { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class AuditEvent : Record { public Guid? ActorId { get; set; } public string Action { get; set; } = ""; public string Detail { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class OutboxEvent : Record { public string Kind { get; set; } = ""; public string Payload { get; set; } = "{}"; public string State { get; set; } = "pending"; public int Attempts { get; set; } public DateTime AvailableAt { get; set; } = DateTime.UtcNow; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public string? Error { get; set; } }
public class WebhookSubscription : Record { public string Url { get; set; } = ""; public string Secret { get; set; } = ""; public bool Active { get; set; } = true; }
public class CommandReceipt : Record { public string Key { get; set; } = ""; public string Operation { get; set; } = ""; public string PayloadHash { get; set; } = ""; public string ResultJson { get; set; } = "{}"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class ReconciliationRun : Record { public int Differences { get; set; } public string DetailJson { get; set; } = "[]"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }

public class ApiCredential : Record { public Guid AccountId { get; set; } public string Name { get; set; } = ""; public string KeyHash { get; set; } = ""; public string ScopesJson { get; set; } = "[]"; public bool Active { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
